const anterior = $input.first().json.data || '';
const atual = $('Preparar Dados Buffer').first().json.mensagemAtual;
const novoBuffer = anterior ? (anterior + '\n' + atual) : atual;
return [{ json: { novoBuffer } }];

const r = $input.first().json;
const telefone = $('Entidades Resolvidas').first().json.telefone;
if (!r.ok) {
  return [{ json: { telefone, salvar: false, resposta_sugerida: r.mensagem || 'Não consegui localizar o registro agora. Tente de novo em alguns minutos.' } }];
}
const pendencia = { tipo: 'leite', registro_id: r.registro_id, descricao: r.descricao };
return [{ json: { telefone, salvar: true, pendencia: JSON.stringify(pendencia), resposta_sugerida: r.mensagem } }];

const msg = (String($('Preparar Entrada Agente').first().json.mensagem_compilada || '')).toLowerCase();
const pendencia = JSON.parse($input.first().json.data);
const telefone = $('Preparar Entrada Agente').first().json.telefone;
const confirmado = /\b(sim|confirma|confirmar|pode)\b/.test(msg);
const cancelado = /\b(nao|não|cancela|cancelar)\b/.test(msg);
return [{ json: { telefone, pendencia, confirmado: confirmado && !cancelado } }];

const msg = $('Webhook').item.json.body.data.message;
// base64 pedido à Evolution (Baixar Áudio); se não vier, o do próprio webhook
const baixado = $('Baixar Áudio (Evolution)').isExecuted ? ($('Baixar Áudio (Evolution)').first().json || {}) : {};
const base64 = baixado.base64 || (msg.audioMessage && msg.audioMessage.base64) || msg.base64 || null;
if (!base64) {
  throw new Error('Audio recebido mas nenhum campo base64 foi encontrado no payload. Verifique a estrutura real do webhook de audio da Evolution API (body.data.message) e ajuste este node.');
}
return [{
  json: {},
  binary: {
    audio: { data: base64, mimeType: 'audio/ogg', fileName: 'audio.ogg' }
  }
}];

const r = $input.first().json;
const telefone = $('Entidades Resolvidas').first().json.telefone;
if (!r.ok) {
  return [{ json: { telefone, salvar: false, resposta_sugerida: r.mensagem || 'Não consegui localizar o registro agora. Tente de novo em alguns minutos.' } }];
}
const pendencia = { tipo: 'financeiro', lancamento_id: r.lancamento_id, descricao: r.descricao };
return [{ json: { telefone, salvar: true, pendencia: JSON.stringify(pendencia), resposta_sugerida: r.mensagem } }];

const dedupeById = (arr) => { const seen = new Set(); return arr.filter(x => { if (!x || !x.id || seen.has(x.id)) return false; seen.add(x.id); return true; }); };
const entidades = $('Entidades Resolvidas').item.json.entidades;
const dataCobertura = entidades.data || new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });

const coberturas = dedupeById($('Get a row').all().map(i => i.json));
let partos = [];
try { partos = dedupeById($('Buscar Partos (Validação Cobertura)').all().map(i => i.json)); } catch (e) {}
const coberturaIdsComParto = new Set(partos.filter(p => p.cobertura_id).map(p => p.cobertura_id));

const duplicada = coberturas.some(c => c.data_cobertura === dataCobertura);
const prenhaConfirmada = coberturas.some(c => c.diagnostico_prenhez === 'positivo' && !coberturaIdsComParto.has(c.id));

let bloqueado = false;
let motivo = '';
if (duplicada) {
  bloqueado = true;
  motivo = `Ja existe uma cobertura registrada pra essa vaca na data ${dataCobertura}. Nao lancei de novo pra evitar duplicidade.`;
} else if (prenhaConfirmada) {
  bloqueado = true;
  motivo = 'Essa vaca ja tem uma prenhez confirmada em aberto (ainda nao pariu). Nao faz sentido registrar nova cobertura antes do parto.';
}

return [{ json: { bloqueado, motivo } }];

const usuario = $json;
let status = 'ok';
let mensagem = '';
if (!usuario.id) {
  status = 'nao_cadastrado';
  mensagem = 'Esse numero de WhatsApp ainda nao esta cadastrado no sistema. Entre em contato com o tecnico responsavel pela sua propriedade pra liberar o acesso.';
} else if (usuario.ativo !== true) {
  status = 'desativado';
  mensagem = 'Seu acesso esta desativado no momento. Entre em contato com o tecnico responsavel pela sua propriedade.';
}
return [{ json: { ...usuario, statusAcesso: status, mensagemAcesso: mensagem } }];

// Este nó roda na rota FALSE do IF (Vaca não encontrada no banco)
return [
  {
    json: {
      sucesso: false,
      resposta_sugerida: "Vaca não localizada no sistema. Por favor, verifique o número ou nome digitado e tente novamente.",
      // Passa os metadados para o fluxo de resposta saber para quem responder
      telefone: $('Identificar Usuario').first().json.telefone || null,
      waba_id: $('Identificar Usuario').first().json.waba_id || null
    }
  }
];

