const msg = $('Webhook').item.json.body.data.message;
const img = msg.imageMessage || {};
// base64 pedido à Evolution (Baixar Foto); se não vier, o do próprio webhook
const baixada = $('Baixar Foto (Evolution)').isExecuted ? ($('Baixar Foto (Evolution)').first().json || {}) : {};
const base64 = baixada.base64 || img.base64 || msg.base64 || null;
if (!base64) {
  throw new Error('Foto recebida mas a Evolution nao devolveu a imagem (Baixar Foto (Evolution) sem base64, e o webhook tambem sem). Confira server_url/apikey da instancia.');
}
const propriedadeId = $('Identificar Usuario').first().json.propriedade_id;
if (!propriedadeId) {
  throw new Error('Foto recebida de um numero sem fazenda cadastrada.');
}
const mime = String(img.mimetype || 'image/jpeg').split(';')[0].trim().toLowerCase();
const ext = mime === 'image/png' ? 'png' : (mime === 'image/webp' ? 'webp' : 'jpg');
const tipo = ext === 'png' ? 'image/png' : (ext === 'webp' ? 'image/webp' : 'image/jpeg');
const nome = Date.now() + '-' + Math.random().toString(36).slice(2, 10) + '.' + ext;
return [{
  json: { caminho: propriedadeId + '/' + nome, legenda: String(img.caption || '').trim() },
  binary: { foto: { data: base64, mimeType: tipo, fileName: nome } }
}];

// Junta o que a IA entendeu com o número achado pelo nome (0061). Nome que não existe ou
// que é de duas vacas vira erro_vaca: o bot pergunta e não grava nada.
const p = $('Parsear Resposta IA').first().json;
let entidades = p.entidades;
let erro_vaca = null;
if ($('Resolver Vaca pelo Nome (RPC)').isExecuted) {
  const r = $('Resolver Vaca pelo Nome (RPC)').first().json || {};
  if (r.ok === false) erro_vaca = r.mensagem || 'Não achei essa vaca. Mande o número do brinco, por exemplo "vaca 12".';
  else if (r.entidades) entidades = Object.assign({}, entidades, r.entidades);
}
return [{ json: { ...p, entidades, erro_vaca }, pairedItem: { item: 0 } }];

